// RustboroCity_Gym (zone 583): generated by converter/gen_interiors.py (no simple people or signs), then its story,
// chapter Ch1 (Sapphire data/maps/RustboroCity_Gym/scripts.inc): Roxanne and the Stone Badge, Rock Tomb, the two gym
// trainers, the guide, the statues. Messages: src/text/script/0374_room_RustboroCity_Gym.txt. Room tiles = Sapphire
// tiles + (1, 0). People and statues: data/story/ch1.json (uid = Sapphire local id): Roxanne 1, Josh 2 and Tommy 3
// (eye-contact trainers: Black 2's global trainer script 3000 + id), the guide 4.
#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_story.inc"

    ScriptEntry Script_1    // Roxanne (RustboroCity_Gym_EventScript_Roxanne)
    ScriptEntry Script_2    // Gym guide (RustboroCity_Gym_EventScript_GymGuide)
    ScriptEntry Script_3    // statues (RustboroCity_Gym_EventScript_LeftGymStatue / RightGymStatue)
    ScriptEntriesEnd

// ---- story
#define RG_ROXANNE 1

Script_1:                                        // trainerbattle_single TRAINER_ROXANNE, ..., RoxanneDefeated, NO_MUSIC
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_defeated TRAINER_ROXANNE, L_RG_Rematch
    TrainerSayMessage TRAINER_ROXANNE, 0, RG_ROXANNE   // Hello, I am Roxanne, the Rustboro Pokémon Gym Leader. ...
    ActorMsgClose                                // (NO_MUSIC: no eye-contact music)
    h_trainerbattle TRAINER_ROXANNE              // (in battle: "So... I lost... Please accept ... the Stone Badge.")
    h_buffer_player                              // RustboroCity_Gym_EventScript_RoxanneDefeated
    SystemMsg 0, 2                               // <player> received the Stone Badge from Roxanne.
    h_badge_fanfare                              // Common_EventScript_PlayGymBadgeFanfare
    MsgWinCloseAll
    h_msgbox_actor 1, RG_ROXANNE                 // The Stone Badge heightens the Attack power of your Pokémon. ...
    h_closemessage
    h_setflag FLAG_DEFEATED_RUSTBORO_GYM
    h_givebadge 1                                // setflag FLAG_BADGE01_GET
    h_setvar VAR_RUSTBORO_STATE, 1
    h_addvar VAR_PETALBURG_GYM_STATE, 1
    h_set_gym_trainers 1                         // Josh and Tommy count as beaten
    h_goto_if_ne VAR_PETALBURG_GYM_STATE, 6, L_RG_GiveRockTomb
    h_clearflag FLAG_HIDE_PETALBURG_GYM_GUIDE    // Common_EventScript_ReadyPetalburgGymForBattle
    h_setflag FLAG_PETALBURG_MART_EXPANDED_ITEMS
L_RG_GiveRockTomb:                               // RustboroCity_Gym_EventScript_GiveRockTomb
    h_giveitem ITEM_TM39
    h_goto_if_eq HLIB_RESULT, 0, L_RG_Release    // (Black 2's item script has said the Bag is full)
    h_setflag FLAG_RECEIVED_TM_ROCK_TOMB
    h_msgbox_actor 2, RG_ROXANNE                 // That TM39 contains Rock Tomb. ...
L_RG_Release:
    h_release
L_RG_Rematch:                                    // (already beaten)
    h_goto_if_unset FLAG_RECEIVED_TM_ROCK_TOMB, L_RG_GiveRockTomb
    h_msgbox 3                                   // Since you are so strong, you should challenge other Gym Leaders. ...
    h_release

Script_2:                                        // RustboroCity_Gym_EventScript_GymGuide
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_DEFEATED_RUSTBORO_GYM, L_RG_GuideVictory
    h_msgbox 4                                   // Yo, how's it going? ...
    h_release
L_RG_GuideVictory:
    h_msgbox 5                                   // Whoa! What a breathtaking victory! ...
    h_release

Script_3:                                        // the statues (lockall; MSGBOX_DEFAULT)
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_goto_if_badge 1, L_RG_StatueCertified
    h_msgbox_info 6                              // Rustboro City Pokémon Gym
    h_closemessage
    h_release
L_RG_StatueCertified:
    h_buffer_player
    h_msgbox_info 7                              // Rustboro City Pokémon Gym / Roxanne's Certified Trainers: <player>
    h_closemessage
    h_release
    .balign 4, 0
